import React from 'react';
import { Link } from 'react-router-dom';
import '../assets/styles/Navbar.css'; // Importing the CSS file for styling
import logo from '../assets/images/logo.png';// Importing the logo image

// Navbar component displays the top navigation bar with links to different pages
const Navbar = () => {
  return (
    <nav className="navbar">
       {/* Logo section */}
      <div className="navbar-logo">
        <img src={logo} alt="GP Logo" />
      </div>

       {/* Navigation links */}
      <ul className="navbar-links">
        <li><Link to="/">Home</Link></li>
        <li><Link to="/about">About Me</Link></li>
        <li><Link to="/projects">Projects</Link></li>
        <li><Link to="/education">Education</Link></li>
        <li><Link to="/services">Services</Link></li>
        <li><Link to="/contact">Contact Me</Link></li>
      </ul>
    </nav>
  );
};

 export default Navbar;
